	public event PropertyChangedEventHandler? PropertyChanged;

	public MainWindow()
	{
		InitializeComponent();
		// 标题带上版本号（和整合包 / 启动器用的是同一个版本号：App.csproj 里的 InformationalVersion）
		Title = $"Sts2CharForge {AppVersion.Current} —— 杀戮尖塔2 自定义角色生成器";
		BuildArtSlots();
		BuildAnimSlots();
		HookAnimationSpec();
		BuildAncientRows();
		PresetItems = CardColorSpec.Presets.Select((CardColorSpec.Preset pz) => new PresetItem(pz, pz.Name)).Append(_customPreset).ToList();
		FrameItems = CardColorSpec.Frames.Select((string f) => new FrameItem(f, f)).Append(_customFrame).ToList();
		// 「诅咒 / 先古卡」页那两个下拉：第一项是「跟角色配色（默认）」，其余和上面的框色一样。
		// 复用同一个 _customFrame 实例，自检里就能用引用比较认出「自定义」。
		SpecialFrameItems = new[] { _followRoleFrame }.Concat(FrameItems).ToList();
		// 诅咒那一栏**没有「自定义」**（用户要求去掉诅咒的自定义颜色选项）：
		// 只给「跟角色配色（默认）」+ 本体的框色名。
		CurseFrameItems = new[] { _followRoleFrame }
			.Concat(FrameItems.Where((FrameItem i) => i.Value is not null)).ToList();
		HookProfileColors();
		// 启动时那份配置也要先把「本体关键词改名」的 7 行补齐（Profile 的 setter 只在换存档时跑）
		EnsureKeywordRenameRows();
		RecheckEnvironment();
		string text = MigrateLegacyProfileFolder();
		NormalizeOutputDir();
		base.DataContext = this;
		ReloadCatalog();
		RefreshAll();
		RefreshProfiles();
		// 遗物列表的「序号」（用户要求第 2 条）：载入存档后先算一遍，
		// 并挂上 CollectionChanged —— 之后任何增删（撤回删除 / 导入 / 自检造数据）都会自动重排
		HookRelicListOrder();
		CardList.SelectionChanged += delegate
		{
			SyncDetail();
			// 换卡之后「右边效果栏锁不键 / 中间费用栏显不显示」要跟着变（锻造卡都藏掉，需求）
			Raise("CardEffectsAreForged");
			Raise("CardEffectsEditable");
			Raise("CardCoreFieldsVisible");
		};
		RelicList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		PotionList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		// 「自定义关键词」和「召唤物」两个列表也必须接上 —— 详情是「换选中项 → 重新指向新对象」，
		// 漏了这两行时详情会**卡在第一次选中的那条上**：在第二条里打字会写进第一条、
		// 图片预览一直显示上一只（用户实测报过：「第一个输入框打不进字、第二个的内容跑到第一个」）。
		KeywordList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		SummonList.SelectionChanged += delegate
		{
			SyncDetail();
		};
		// 新增的两页：「自定义参数 / 组」与「锻造」"
		ParamList.SelectionChanged += OnParamSelectionChanged;
		GroupList.SelectionChanged += OnGroupSelectionChanged;
		GroupCardList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("GroupCardRows") { Source = this });
		ForgeItemList.SelectionChanged += delegate
		{
			SyncForgeDetail();
		};
		ForgeItemList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("ForgeVisible") { Source = this });
		// 节点图那块布：改了图（加模块 / 连线 / 拖动）之后刷新说明与问题列表
		ForgeCanvas.Changed += delegate
		{
			Raise("ForgeGraphTabHint");
			RefreshIssues();
		};
		// 积木编辑器：拖块 / 加块 / 删块都会把树写回图（只重建连线，节点还是同一批）。"
		// 写完把节点图也重画一遍，让「节点图 → 积木」两个视图看到的是同一块布。"
		ForgeBlocks.Changed += delegate
		{
			ForgeCanvas?.Rebuild();
			Raise("ForgeGraphTabHint");
			RefreshIssues();
		};
		// 锻造页左上角那四个分类单选：**在 XAML 里不按 Checked**（解析到一半就会触发，后面的控件还没造出来），"
		// 等所有控件都在了再挂。"
		ForgeKindNone.Checked += OnForgeKindChanged;
		ForgeKindCard.Checked += OnForgeKindChanged;
		ForgeKindPotion.Checked += OnForgeKindChanged;
		ForgeKindRelic.Checked += OnForgeKindChanged;
		// 所有控件都造好了：这一页现在可以安全刷新 
		_uiReady = true;
		RefreshForgeList();
		SetStatus(text ?? "就绪。填好配置 → 「① 生成工程」→「② 一键构建 + 安装」。");
	}

	private void SyncDetail()
	{
		CardDetail.DataContext = CardList.SelectedItem;
		RelicDetail.DataContext = RelicList.SelectedItem;
		PotionDetail.DataContext = PotionList.SelectedItem;
		KeywordDetail.DataContext = KeywordList.SelectedItem;
		Raise("CustomKeywordRows");
		Raise("KeywordChoices");
		// 需求 ⑦：「生成出来的卡加上关键词」的下拉与自定义关键词注册联动（同源的那一份候选）
		Raise("SpawnKeywordChoices");
		// 关键词改了名字 / 加了删了 → 「范围限定」里那一组选项跟着变（生成 / 变化卡牌能只从这一组里出牌）
		RefreshCustomKeywordRegistry();
		Raise("HasCustomKeywords");
		Raise("NoCustomKeywords");
		Raise("SelectedCardUpgradeCost");
		Raise("UpgradeCostHint");
		Raise("UpgradeKeywordRows");
		// 召唤物：图片预览 + 效果编辑器「召唤物（哪一只）」下拉的候选（只列已启用的）
		Raise("SelectedSummonImagePreview");
		RaisePetSummonChoices();
		CardList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.Cards"));
		RelicList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.Relics"));		PotionList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.Potions"));
		KeywordList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CustomKeywords"));
		SummonList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.Summons"));
		CardEffectList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Effects"));
		// 第 10 批：遗物页的「触发时机列表」绑到当前选中遗物的 Triggers；
		// 效果列表绑到**当前选中那条时机**的 Effects（选中项由 OnRelicTriggerSelectionChanged 换绑）。
		if (RelicList.SelectedItem is RelicSpec selRelic)
		{
			if (selRelic.Triggers.Count == 0) selRelic.Triggers.Add(new RelicTriggerSpec());
			RelicTriggerList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Triggers") { Source = selRelic });
			if (RelicTriggerList.SelectedItem is null) RelicTriggerList.SelectedIndex = 0;
		}
		else
		{
			RelicTriggerList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Triggers"));
		}
		RelicTriggerList.SelectionChanged -= OnRelicTriggerSelectionChanged;
		RelicTriggerList.SelectionChanged += OnRelicTriggerSelectionChanged;
		OnRelicTriggerSelectionChanged(RelicTriggerList, new SelectionChangedEventArgs(ListBox.SelectionChangedEvent, new List<object>(), new List<object>()));
		Raise("RelicTriggerSummary");
		// ⚠ 这里**不能**再把 RelicEffectList 绑到裸 "Effects"（RelicDetail 的 DataContext 是 RelicSpec，
		// 那会绑回「第 1 条时机」）——它的 ItemsSource 在 XAML 里已经绑成
		// `SelectedItem.Effects, ElementName=RelicTriggerList`，OnRelicTriggerSelectionChanged 也会换绑。
		RelicEffectList.SelectionChanged -= OnRelicEffectSelectionChanged;
		RelicEffectList.SelectionChanged += OnRelicEffectSelectionChanged;
		PotionEffectList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Effects"));
		// 新增的两页：列表数据源 + 算出来的候选"
		ParamList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CustomParams"));
		GroupList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("Profile.CardGroups"));
		GroupCardList.SetBinding(ItemsControl.ItemsSourceProperty, new Binding("GroupCardRows") { Source = this });
		Raise("CardGroupRows");
		Raise("NoCardGroups");
		Raise("CardGroupRowHint");
		Raise("ParamChoices");
		Raise("ParamGrantChoices");
		Raise("ParamSummaryRows");
		Raise("ParamNameWarnText");
		Raise("ParamSourceHint");
		RaiseGroupsChanged();
		RaiseCardPortrait();
		Raise("RelicIconPreview");
	}

