		Check("所有「选择路径」动作名都在清单里", EnvItems.Where((EnvCheckItem i) => i.CanPick).All((EnvCheckItem i) => EnvCheck.PickActions.ContainsKey(i.Pick)), string.Join(" | ", from i in EnvItems
			where i.CanPick
