					Check("从工程恢复（带复制附加处理）：没认出来的语句为 0", !cpRec.HasUnparsed, cpRec.Unparsed.FirstOrDefault() ?? "全部认出来了");
				}
				finally
				{
					try { Directory.Delete(cpRoot, true); } catch { }
